  "opt.success": { en: "success", fr: "réussite", es: "éxito", pt: "sucesso", de: "Erfolg", ru: "успех", pl: "sukces", zh: "成功率", ja: "成功率", hi: "सफलता", ar: "نجاح", bn: "সাফল্য", ur: "کامیابی" },
  "opt.defaultProb": { en: "probability = route default (no run for this character yet)", fr: "proba = difficulté par défaut (aucun run de ce perso pour l'instant)", es: "probabilidad = dificultad por defecto (aún sin partidas con este personaje)", pt: "probabilidade = dificuldade padrão (ainda sem runs deste personagem)", de: "Wahrscheinlichkeit = Standardschwierigkeit (noch kein Run mit diesem Charakter)", ru: "вероятность = базовая сложность (забегов этим персонажем ещё нет)", pl: "prawdopodobieństwo = domyślna trudność (brak runów tą postacią)", zh: "概率 = 路线默认难度（该角色暂无对局）", ja: "確率＝ルート既定値（このキャラのラン記録なし）", hi: "संभावना = मार्ग की डिफ़ॉल्ट (इस पात्र का कोई रन नहीं)", ar: "الاحتمال = صعوبة المسار الافتراضية (لا جولات بهذه الشخصية بعد)", bn: "সম্ভাবনা = রুটের ডিফল্ট (এই চরিত্রের রান নেই)", ur: "امکان = روٹ کا ڈیفالٹ (اس کردار کا کوئی رن نہیں)" },
  "opt.coldStart": { en: "No stats data yet: the probabilities shown are each route's default difficulty. Install the companion mod and play — the ranking will adjust to your mastery of each character.", fr: "Aucune donnée de stats pour l'instant : les probabilités affichées sont les difficultés par défaut de chaque route. Installe le mod compagnon et joue — le classement s'ajustera à ta maîtrise de chaque perso.", es: "Aún sin estadísticas: las probabilidades son la dificultad por defecto de cada ruta. Instala el mod y juega — el ranking se ajustará a tu dominio de cada personaje.", pt: "Ainda sem estatísticas: as probabilidades são a dificuldade padrão de cada rota. Instale o mod e jogue — o ranking se ajustará ao seu domínio de cada personagem.", de: "Noch keine Statistiken: die Wahrscheinlichkeiten sind die Standardschwierigkeit jeder Route. Installiere den Mod und spiele — das Ranking passt sich deinem Können an.", ru: "Пока нет статистики: показаны базовые сложности маршрутов. Установите мод и играйте — рейтинг подстроится под ваше мастерство.", pl: "Brak statystyk: pokazane prawdopodobieństwa to domyślna trudność tras. Zainstaluj moda i graj — ranking dopasuje się do twoich umiejętności.", zh: "暂无统计数据：显示的概率为各路线的默认难度。安装配套 mod 并游玩——排名会根据你对各角色的熟练度调整。", ja: "統計データがまだありません：表示中の確率は各ルートの既定難易度です。mod を導入して遊べば、順位はあなたのキャラ習熟度に合わせて調整されます。", hi: "अभी कोई आँकड़े नहीं: दिखाई गई संभावनाएँ प्रत्येक मार्ग की डिफ़ॉल्ट कठिनाई हैं। मॉड इंस्टॉल कर खेलें — रैंकिंग आपकी दक्षता अनुसार ढलेगी।", ar: "لا إحصاءات بعد: الاحتمالات المعروضة هي الصعوبة الافتراضية لكل مسار. ثبّت المود والعب — سيتكيّف الترتيب مع إتقانك لكل شخصية.", bn: "এখনও পরিসংখ্যান নেই: দেখানো সম্ভাবনা প্রতিটি রুটের ডিফল্ট কাঠিন্য। মড ইনস্টল করে খেলুন — র‍্যাঙ্কিং আপনার দক্ষতা অনুযায়ী মানিয়ে নেবে।", ur: "ابھی شماریات نہیں: دکھائے گئے امکانات ہر روٹ کی ڈیفالٹ مشکل ہیں۔ ماڈ انسٹال کر کے کھیلیں — درجہ بندی آپ کی مہارت کے مطابق ڈھل جائے گی۔" },
  "opt.charsMissing": { en: "character(s)", fr: "perso(s)", es: "personaje(s)", pt: "personagem(ns)", de: "Charakter(e)", ru: "персонажей", pl: "postaci", zh: "个角色", ja: "キャラ", hi: "पात्र", ar: "شخصيات", bn: "চরিত্র", ur: "کردار" },
