  "opt.marks": { en: "mark(s)", fr: "marque(s)", es: "marca(s)", pt: "marca(s)", de: "Marke(n)", ru: "меток", pl: "znaczników", zh: "个标记", ja: "マーク", hi: "मार्क", ar: "علامات", bn: "মার্ক", ur: "مارکس" },
  "opt.items": { en: "item(s)", fr: "objet(s)", es: "objeto(s)", pt: "item(ns)", de: "Gegenstand/-stände", ru: "предметов", pl: "przedmiot(y)", zh: "件物品", ja: "アイテム", hi: "आइटम", ar: "أغراض", bn: "আইটেম", ur: "آئٹمز" },

  // ═══ Build assistant ═══
  "bld.sub": { en: "Simulator: compose your build, then \"test\" a candidate item to see the delta, the synergy and the verdict. Offline, factual — not EID, no game assets.", fr: "Simulateur : compose ton build, puis « teste » un item candidat pour voir le delta, la synergie et le verdict. Hors-ligne, factuel — pas d'EID, aucun asset du jeu.", es: "Simulador: compón tu build y luego «prueba» un objeto candidato para ver el delta, la sinergia y el veredicto. Sin conexión, factual — no es EID, sin assets del juego.", pt: "Simulador: monte seu build e depois \"teste\" um item candidato para ver o delta, a sinergia e o veredito. Offline, factual — não é EID, sem assets do jogo.", de: "Simulator: stelle deinen Build zusammen und „teste\" dann einen Kandidaten-Gegenstand für Delta, Synergie und Urteil. Offline, faktisch — kein EID, keine Spiel-Assets.", ru: "Симулятор: соберите билд, затем «протестируйте» предмет-кандидат — дельта, синергия и вердикт. Офлайн, по фактам — не EID, без ассетов игры.", pl: "Symulator: złóż build, a potem „przetestuj\" kandydujący przedmiot — delta, synergia i werdykt. Offline, faktograficznie — to nie EID, bez assetów gry.", zh: "模拟器：搭配你的 build，再「测试」候选道具，查看数值变化、协同与结论。离线、只讲事实——不是 EID，不含游戏素材。", ja: "シミュレーター：ビルドを組み、候補アイテムを「テスト」して差分・シナジー・判定を確認。オフラインかつ事実ベース — EID ではなく、ゲーム素材も不使用。", hi: "सिम्युलेटर: अपना बिल्ड बनाएँ, फिर किसी उम्मीदवार आइटम को «टेस्ट» करें — डेल्टा, तालमेल और निर्णय। ऑफ़लाइन, तथ्यात्मक — EID नहीं, कोई गेम एसेट नहीं।", ar: "محاكي: كوّن بناءك ثم «اختبر» غرضًا مرشّحًا لرؤية الفارق والتآزر والحكم. بدون إنترنت وواقعي — ليس EID، وبلا أصول من اللعبة.", bn: "সিমুলেটর: আপনার বিল্ড সাজান, তারপর একটি প্রার্থী আইটেম «টেস্ট» করুন — ডেল্টা, সমন্বয় ও রায়। অফলাইন, তথ্যভিত্তিক — EID নয়, গেম অ্যাসেট নেই।", ur: "سمیولیٹر: اپنا بلڈ بنائیں، پھر کسی امیدوار آئٹم کو «ٹیسٹ» کریں — فرق، ہم آہنگی اور فیصلہ۔ آف لائن، حقائق پر مبنی — EID نہیں، گیم اثاثے نہیں۔" },
