  "diag.step1": { en: "Close and restart the game (mods load at startup).", fr: "Ferme et relance le jeu (les mods se chargent au lancement).", es: "Cierra y reinicia el juego (los mods se cargan al arrancar).", pt: "Feche e reinicie o jogo (mods carregam na inicialização).", de: "Schließe und starte das Spiel neu (Mods laden beim Start).", ru: "Закройте и перезапустите игру (моды грузятся при запуске).", pl: "Zamknij i uruchom grę ponownie (mody ładują się przy starcie).", zh: "关闭并重启游戏（mod 在启动时加载）。", ja: "ゲームを閉じて再起動してください（mod は起動時に読み込まれます）。", hi: "गेम बंद कर फिर चालू करें (मॉड शुरुआत में लोड होते हैं)।", ar: "أغلق اللعبة وأعد تشغيلها (تُحمَّل المودات عند البدء).", bn: "গেম বন্ধ করে চালু করুন (মড শুরুতে লোড হয়)।", ur: "گیم بند کر کے دوبارہ چلائیں (ماڈز اسٹارٹ اپ پر لوڈ ہوتے ہیں)۔" },
  "diag.step2": { en: "The \"modded\" watermark will appear — harmless once Mom has been beaten on this slot.", fr: "Le watermark « modded » apparaîtra — inoffensif une fois Mom battue sur ce slot.", es: "Aparecerá la marca «modded» — inofensiva una vez vencida Mom en esta partida.", pt: "A marca \"modded\" aparecerá — inofensiva depois de vencer Mom neste slot.", de: "Das „modded\"-Wasserzeichen erscheint — harmlos, sobald Mom auf diesem Slot besiegt wurde.", ru: "Появится водяной знак «modded» — безвреден, если Mom уже побеждена на этом слоте.", pl: "Pojawi się znak „modded\" — nieszkodliwy, gdy Mom została pokonana na tym slocie.", zh: "会出现「modded」水印——在该存档击败 Mom 后无影响。", ja: "「modded」の透かしが表示されます — このスロットで Mom を倒していれば無害です。", hi: "«modded» वॉटरमार्क दिखेगा — इस स्लॉट पर Mom हराने के बाद हानिरहित।", ar: "ستظهر علامة «modded» — غير ضارة بعد هزيمة Mom في هذه الخانة.", bn: "«modded» ওয়াটারমার্ক দেখাবে — এই স্লটে Mom হারানোর পর ক্ষতিকর নয়।", ur: "«modded» واٹر مارک ظاہر ہوگا — اس سلاٹ پر Mom کو ہرانے کے بعد بے ضرر۔" },
  "diag.step3": { en: "On a NEW save: beat Mom once before relying on unlocks (a game rule, not a tracker rule).", fr: "Sur une NOUVELLE sauvegarde : bats Mom une fois avant de compter sur les déblocages (règle du jeu, pas du tracker).", es: "En una partida NUEVA: vence a Mom una vez antes de confiar en los desbloqueos (regla del juego, no del tracker).", pt: "Num save NOVO: derrote Mom uma vez antes de contar com os desbloqueios (regra do jogo, não do tracker).", de: "Bei einem NEUEN Spielstand: besiege Mom einmal, bevor du dich auf Freischaltungen verlässt (Spielregel, nicht Tracker-Regel).", ru: "На НОВОМ сохранении: победите Mom один раз, прежде чем полагаться на разблокировки (правило игры, не трекера).", pl: "Na NOWYM zapisie: pokonaj Mom raz, zanim zaczniesz liczyć na odblokowania (zasada gry, nie trackera).", zh: "在新存档上：先击败一次 Mom 再指望解锁（这是游戏规则，不是本工具的规则）。", ja: "新規セーブでは：解除を当てにする前に一度 Mom を倒してください（ゲーム側のルールです）。", hi: "नए सेव पर: अनलॉक पर भरोसा करने से पहले एक बार Mom को हराएँ (गेम का नियम)।", ar: "على حفظ جديد: اهزم Mom مرة قبل الاعتماد على الفتوحات (قاعدة اللعبة لا الأداة).", bn: "নতুন সেভে: আনলকের উপর ভরসা করার আগে একবার Mom হারান (গেমের নিয়ম)।", ur: "نئے سیو پر: اَن لاکس پر بھروسا کرنے سے پہلے ایک بار Mom کو ہرائیں (گیم کا اصول)۔" },
  "diag.steamSave": { en: "Steam Cloud save detected", fr: "Save Steam Cloud détectée", es: "Partida de Steam Cloud detectada", pt: "Save do Steam Cloud detectado", de: "Steam-Cloud-Spielstand erkannt", ru: "Найдено сохранение Steam Cloud", pl: "Wykryto zapis Steam Cloud", zh: "已检测到 Steam Cloud 存档", ja: "Steam Cloud のセーブを検出", hi: "Steam Cloud सेव मिला", ar: "رُصد حفظ Steam Cloud", bn: "Steam Cloud সেভ শনাক্ত", ur: "Steam Cloud سیو ملا" },

